use vstd::prelude::*;

verus! {
    fn find_first_occurrence(arr: &Vec<i32>, target: i32) -> (index: Option<usize>)
        requires
            arr.len() <= usize::MAX,
        ensures
            match index {
                Some(i) => i < arr.len() && arr[i] == target && 
                            forall(|j: usize| j < i ==> arr[j] != target),
                None => forall(|j: usize| j < arr.len() ==> arr[j] != target),
            },
    {
        let mut left: usize = 0;
        let mut right: usize = arr.len();
        let mut result: Option<usize> = None;

        while left < right
            invariant
                left <= right,
                result == None || (result.is_some() && result.unwrap() < arr.len() && arr[result.unwrap()] == target),
                forall(|j: usize| j < left ==> arr[j] != target),
                forall(|j: usize| j < right ==> arr[j] <= target),
            decreases right - left,
        {
            let mid: usize = left + (right - left) / 2;

            if arr[mid] < target {
                left = mid + 1;
            } else {
                if arr[mid] == target {
                    result = Some(mid);
                    right = mid; // continue searching in the left part
                } else {
                    right = mid; // search in the left part
                }
            }
        }

        if result.is_some() {
            // We found a potential index, now we need to ensure it's the first occurrence
            let idx = result.unwrap();
            while idx > 0 && arr[idx - 1] == target {
                idx = idx - 1;
            }
            Some(idx)
        } else {
            None
        }
    }
}
